class RemoteCallCounter:
    def __init__(self, monkeypatch):
        import boxyard._utils.rclone as rclone_module

        self.calls = []
        self._original = rclone_module.run_cmd_async

        async def _counting(cmd, *args, **kwargs):
            self.calls.append(cmd)
            return await self._original(cmd, *args, **kwargs)

        monkeypatch.setattr(rclone_module, "run_cmd_async", _counting)

    def __len__(self):
        return len(self.calls)

