def test_the_filter_collapses_a_clean_pass(temp_boxyard, monkeypatch):
    """
    With nothing changed on either side, a filtered META pass must cost far
    less than an unfiltered one. If this ever regresses, the whole point of
    B-prime is gone and the fast loop is back to ~6.6 min on the real yard.
    """
    remote_name, _, config, config_path, _ = temp_boxyard
    for i in range(5):
        _make_box(config_path, remote_name, f"box-{i}")

    # Sync once so both sides agree and the check records exist.
    _run(config_path, "-c", "meta")
    _run(config_path, "-c", "meta", "--skip-unchanged-meta")

    unfiltered = RemoteCallCounter(monkeypatch)
    _run(config_path, "-c", "meta")
    unfiltered_calls = len(unfiltered)

    filtered = RemoteCallCounter(monkeypatch)
    _run(config_path, "-c", "meta", "--skip-unchanged-meta")
    filtered_calls = len(filtered)

    print(
        f"\n  5 boxes, nothing changed: "
        f"unfiltered={unfiltered_calls} remote calls, "
        f"filtered={filtered_calls}"
    )
    assert unfiltered_calls > 0, "the counter caught nothing -- it is vacuous"
    assert filtered_calls < unfiltered_calls, (
        f"the filter saved nothing: {filtered_calls} vs {unfiltered_calls}"
    )
    # The filter's cost is a FIXED two listings; the unfiltered pass grows with
    # the box count. Asserting a ratio rather than "fewer" keeps the test
    # meaningful: on the real 590-box yard this is ~1,180 calls against ~2.
    assert filtered_calls <= unfiltered_calls / 2, (
        f"the filter saved only {unfiltered_calls - filtered_calls} of "
        f"{unfiltered_calls} calls; expected at least half"
    )


def test_the_filter_still_syncs_a_box_whose_local_meta_changed(temp_boxyard):
    """
    A local edit must reach the remote even though the remote has not moved.
    This is the half a naive remote-only filter would silently drop -- fast
    inbox, dead outbox.
    """
    remote_name, _, config, config_path, _ = temp_boxyard
    index_name = _make_box(config_path, remote_name, "edited-box")
    _run(config_path, "-c", "meta", "--skip-unchanged-meta")

    config = get_boxyard_meta(config) and config
    metas = get_boxyard_meta(config).box_metas
    meta = next(m for m in metas if m.index_name == index_name)
    assert not local_meta_differs_from_base(config, meta), "should start agreed"

    modify_boxmeta(
        config_path=config_path,
        box_index_name=index_name,
        modifications={"groups": ["a-new-group"]},
    )
    metas = get_boxyard_meta(config).box_metas
    meta = next(m for m in metas if m.index_name == index_name)
    assert local_meta_differs_from_base(config, meta), (
        "a local edit was not detected -- it would never be pushed"
    )

    needed, skipped = meta_boxes_needing_sync(
        config, [meta], {index_name: _remote_stamp(config, index_name)}
    )
    assert needed == [index_name]
    assert skipped == []


def _remote_stamp(config, index_name):
    """The (ModTime, Size) the check record last saw, i.e. 'remote unmoved'."""
    record = read_check_record(config, index_name, BoxPart.META)
    if record is None:
        return (None, None)
    return (record.get("remote_modtime"), record.get("remote_size"))

