def test_a_box_missing_from_the_listing_is_never_skipped(temp_boxyard):
    """
    Absent from the bulk listing means new here, deleted there, or on a storage
    location the listing did not cover. Every one of those wants the real sync
    path to look.
    """
    remote_name, _, config, config_path, _ = temp_boxyard
    index_name = _make_box(config_path, remote_name, "ghost-box")
    _run(config_path, "-c", "meta", "--skip-unchanged-meta")

    metas = get_boxyard_meta(config).box_metas
    needed, skipped = meta_boxes_needing_sync(config, metas, {})
    assert needed == [index_name]
    assert skipped == []


def test_a_box_with_no_merge_base_is_never_skipped(temp_boxyard):
    """
    No base means "cannot tell whether there is a local edit", which must cost
    a sync rather than skip one. This is what makes the upgrade safe: every box
    is checked once, then settles.
    """
    remote_name, _, config, config_path, _ = temp_boxyard
    index_name = _make_box(config_path, remote_name, "baseless-box")
    _run(config_path, "-c", "meta", "--skip-unchanged-meta")

    metas = get_boxyard_meta(config).box_metas
    meta = metas[0]
    base_path = meta.get_local_meta_base_path(config)
    assert base_path.exists()
    base_path.unlink()

    needed, _ = meta_boxes_needing_sync(
        config, [meta], {index_name: _remote_stamp(config, index_name)}
    )
    assert needed == [index_name]


def test_an_unchanged_box_is_skippable(temp_boxyard):
    """The positive case -- without it the tests above could all pass vacuously."""
    remote_name, _, config, config_path, _ = temp_boxyard
    index_name = _make_box(config_path, remote_name, "quiet-box")
    _run(config_path, "-c", "meta", "--skip-unchanged-meta")

    metas = get_boxyard_meta(config).box_metas
    meta = metas[0]
    needed, skipped = meta_boxes_needing_sync(
        config, [meta], {index_name: _remote_stamp(config, index_name)}
    )
    assert skipped == [index_name], (needed, skipped)
    assert needed == []


def test_a_box_that_failed_is_never_stamped(temp_boxyard, monkeypatch):
    """
    The most dangerous wrong answer this filter could give.

    The post-pass stamping records "the remote looked like this when we
    reconciled". Stamping a box whose sync ERRORED would record a
    reconciliation that never happened -- and because the stamp is what makes a
    box skippable, that box would be skipped on every subsequent pass. A box
    that fails once would go silently un-synced forever, reporting nothing.

    Constructed so the two outcomes are DISTINGUISHABLE: sync cleanly first so
    a stamp exists, then move the remote boxmeta so the listing reports a new
    one, then fail the sync. A correct pass leaves the OLD stamp (box still
    needs work); a pass that stamps regardless adopts the new one (box goes
    quiet).
    """
    import os

    import boxyard.cmds as cmds_module

    remote_name, remote_rclone_path, config, config_path, _ = temp_boxyard
    index_name = _make_box(config_path, remote_name, "doomed-box")
    _run(config_path, "-c", "meta", "--skip-unchanged-meta")

    before = read_check_record(config, index_name, BoxPart.META)
    assert before is not None and before.get("remote_modtime") is not None, (
        "setup failed: the clean pass did not stamp the box"
    )

    # Move the remote's boxmeta on, so a wrongful stamp would be visibly different.
    remote_meta = (
        remote_rclone_path / "boxyard" / "boxes" / index_name / "boxmeta.toml"
    )
    assert remote_meta.exists(), remote_meta
    remote_meta.write_text(remote_meta.read_text() + "\n# nudged\n")
    os.utime(remote_meta, (time.time() + 120, time.time() + 120))

    async def _explode(*args, **kwargs):
        raise RuntimeError("remote went away")

    monkeypatch.setattr(cmds_module, "sync_box", _explode)
    _run(config_path, "-c", "meta", "--skip-unchanged-meta")

    after = read_check_record(config, index_name, BoxPart.META)
    assert after["remote_modtime"] == before["remote_modtime"], (
        "a box whose sync FAILED adopted the remote's new stamp; it would now "
        f"be skipped on every future pass. before={before!r} after={after!r}"
    )

    # ...and it is still selected next time.
    metas = get_boxyard_meta(config).box_metas
    needed, skipped = meta_boxes_needing_sync(
        config, metas, {index_name: ("2026-01-01T00:00:00Z", 123)}
    )
    assert needed == [index_name]
    assert skipped == []
